const item = $input.item;
const body = item.json;
const binaryKeys = Object.keys(item.binary ?? {});

// Support both multipart file upload and JSON with imageUrl
let screenshotProperty = null;
let errorLogs = '';
let projectKey = '';
let originalFileName = 'screenshot.png';
let mimeType = 'image/png';

if (binaryKeys.length > 0) {
  // Multipart form upload with binary file
  screenshotProperty = binaryKeys[0];
  const screenshot = item.binary[screenshotProperty];
  originalFileName = screenshot.fileName || 'screenshot.png';
  mimeType = screenshot.mimeType || 'image/png';
  errorLogs = body.errorLogs || body['Error logs'] || '';
  projectKey = String(body.projectKey || body['Jira project key'] || '').trim().toUpperCase();
} else if (body.imageUrl) {
  // JSON payload with imageUrl - will be handled by downstream nodes
  screenshotProperty = null;
  errorLogs = body.errorLogs || body['Error logs'] || '';
  projectKey = String(body.projectKey || body['Jira project key'] || '').trim().toUpperCase();
} else {
  throw new Error('No screenshot file or imageUrl provided. Send multipart form with file or JSON with imageUrl.');
}

return [{
  json: {
    screenshotProperty,
    originalFileName,
    mimeType,
    errorLogs,
    projectKey,
    imageUrl: body.imageUrl || null
  },
  binary: item.binary
}];

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const property = item.json.screenshotProperty;

  if (item.json.imageUrl) {
    // Handle imageUrl from JSON payload - pass through for HTTP download
    results.push({
      json: {
        ...item.json,
        imageDataUrl: item.json.imageUrl
      },
      binary: item.binary
    });
  } else if (property && item.binary?.[property]) {
    // Handle binary file upload
    const buffer = await this.helpers.getBinaryDataBuffer(i, property);
    const base64 = buffer.toString('base64');
    results.push({
      json: {
        ...item.json,
        imageDataUrl: `data:${item.json.mimeType};base64,${base64}`
      },
      binary: item.binary
    });
  } else {
    throw new Error('Screenshot binary data is unavailable and no imageUrl provided.');
  }
}
return results;

